@ApiOperation(value = "刷新单个单证素材id")
    @PostMapping("/refreshMediaIdByDocNum")
    public GenericRpcResponse<Boolean> refreshMediaIdByDocNum(@RequestParam(value = "docNum") String docNum) {
        productDocExampleService.refreshMediaIdByDocNum(docNum);
        return GenericRpcResponse.success(true);
    }

@Override
    public void refreshMediaIdByDocNum(String docNum) {
        DocExampleE docExampleE = docExampleFactory.selectByDocNum(docNum);
        docExampleE.setGmtModified(new Date());
        WecomMediaResponseInfo responseInfo = getMediaIdFromCache(docExampleE);
        if (StringUtils.isNotBlank(responseInfo.getCreatedAt())) {
            docExampleE.setMediaId(responseInfo.getMediaId());
            docExampleE.setCreatedAt(new Date(Long.parseLong(responseInfo.getCreatedAt()) * 1000));
        }
        docExampleFactory.updateByDocNum(docExampleE);
    }

public DocExampleE selectByDocNum(String docNum) {
        return repository.selectByDocNum(docNum);
    }

@Override
    public DocExampleDO selectByDocNum(String docNum) {
        return docExampleMapper.selectByDocNum(docNum);
    }

@Test
    public void selectByDocNum() {

        PowerMockito.when(docExampleMapper.selectByDocNum(any())).thenReturn(new DocExampleDO());
        DocExampleDO res = tunnel.selectByDocNum("3");
        Assert.assertNotNull(res);

    }
